INSERT INTO requirements (id, project_id, title, description, type, priority, acceptance_criteria, owner_id, status, evidence_required, req_order, req_code, project_sub_id, is_deleted, ai_generated, created_by, created_at, updated_at) VALUES (102, 1, 'Student Account Registration and Login', 'Students must be able to register and log in to the system using either their email address or social accounts (e.g., Google, Facebook).', 'SECURITY'::requirement_type_enum, 'CRITICAL'::priority_enum, '["Given a new student registers with email, then their account information must be securely encrypted and stored, protected from unauthorized access (Data Security & Privacy).", "Given a registered student attempts to log in, then the authentication process must be highly available and complete within 2 seconds (High Availability).", "When a student logs in, the system must enforce strict data privacy protocols for their personal information (Data Security & Privacy).", "The authentication system must be capable of handling a continuously growing number of concurrent login requests without degradation in performance (Scalability)."]'::jsonb, 1, 'DRAFT'::requirement_status_enum, FALSE, NULL, 'REQ-1', 1, FALSE, TRUE, 1, '2026-06-18 07:36:30.278203', '2026-06-18 07:36:30.278203') ON CONFLICT (id) DO NOTHING;
INSERT INTO requirements (id, project_id, title, description, type, priority, acceptance_criteria, owner_id, status, evidence_required, req_order, req_code, project_sub_id, is_deleted, ai_generated, created_by, created_at, updated_at) VALUES (103, 1, 'Tutor Profile Search and Filtering', 'Students can search for tutors based on criteria such as subject, expertise, language, teaching style, hourly rate, rating, and availability.', 'FUNCTIONAL'::requirement_type_enum, 'HIGH'::priority_enum, '["When a student performs a tutor search, the system must return accurate results based on the specified criteria in real-time (Real-time Scheduling Accuracy).", "The search functionality must remain responsive and available even during peak usage times with a large number of tutor profiles (High Availability).", "The search index and related data must be scalable to accommodate a continuously growing database of tutors and their attributes without performance degradation (Scalability).", "All tutor profile data accessed through search must adhere to data privacy regulations (Data Security & Privacy)."]'::jsonb, 1, 'DRAFT'::requirement_status_enum, FALSE, NULL, 'REQ-2', 2, FALSE, TRUE, 1, '2026-06-18 07:36:30.307634', '2026-06-18 07:36:30.307634') ON CONFLICT (id) DO NOTHING;
INSERT INTO requirements (id, project_id, title, description, type, priority, acceptance_criteria, owner_id, status, evidence_required, req_order, req_code, project_sub_id, is_deleted, ai_generated, created_by, created_at, updated_at) VALUES (104, 1, 'Tutor Profile Viewing', 'Each tutor profile must display comprehensive information including educational background, certifications, experience, subjects taught, reviews, and teaching methods.', 'FUNCTIONAL'::requirement_type_enum, 'HIGH'::priority_enum, '["When a student views a tutor profile, all displayed information must be accurate and up-to-date (Real-time Scheduling Accuracy - for availability).", "The system must retrieve and display tutor profiles quickly, ensuring high availability of this information (High Availability).", "Tutor profile data, especially sensitive certifications or personal details, must be securely stored and only accessible to authorized viewers (Data Security & Privacy).", "The tutor profile infrastructure must scale efficiently to handle a large number of tutor profiles and concurrent views (Scalability)."]'::jsonb, 1, 'DRAFT'::requirement_status_enum, FALSE, NULL, 'REQ-3', 3, FALSE, TRUE, 1, '2026-06-18 07:36:30.309645', '2026-06-18 07:36:30.309645') ON CONFLICT (id) DO NOTHING;
INSERT INTO requirements (id, project_id, title, description, type, priority, acceptance_criteria, owner_id, status, evidence_required, req_order, req_code, project_sub_id, is_deleted, ai_generated, created_by, created_at, updated_at) VALUES (105, 1, 'Tutoring Session Scheduling', 'Students can select a tutor and book online or offline sessions. Before confirming a booking, students choose a date, time slot, duration, and learning mode. Tutors can define their available time slots.', 'FUNCTIONAL'::requirement_type_enum, 'CRITICAL'::priority_enum, '["When a student attempts to book a session, the system must accurately display and update tutor availability in real-time, preventing double-bookings (Real-time Scheduling Accuracy).", "The scheduling mechanism must be highly available, allowing students to book and tutors to manage availability without service interruptions (High Availability).", "All booking data, including student and tutor details, session times, and learning mode, must be securely stored and protected (Data Security & Privacy).", "The scheduling system must scale to handle thousands of concurrent booking requests and updates from a large user base (Scalability).", "Upon successful booking (post-payment), the system must ensure the integrity of the booking record and payment linkage (Payment Processing Integrity)."]'::jsonb, 1, 'DRAFT'::requirement_status_enum, FALSE, NULL, 'REQ-4', 4, FALSE, TRUE, 1, '2026-06-18 07:36:30.311151', '2026-06-18 07:36:30.311151') ON CONFLICT (id) DO NOTHING;
INSERT INTO requirements (id, project_id, title, description, type, priority, acceptance_criteria, owner_id, status, evidence_required, req_order, req_code, project_sub_id, is_deleted, ai_generated, created_by, created_at, updated_at) VALUES (106, 1, 'Automated Tutor Recommendation', 'If a student does not select a specific tutor, the system automatically recommends suitable tutors based on subject requirements and previous learning history, optionally powered by AI.', 'FUNCTIONAL'::requirement_type_enum, 'HIGH'::priority_enum, '["Given a student requests recommendations, the system must provide relevant tutor suggestions based on their learning history in real-time (Real-time Scheduling Accuracy - for immediate booking).", "The recommendation engine must be highly available and generate results promptly to enhance user experience (High Availability).", "The system must ensure that student learning history used for recommendations is anonymized or handled with strict privacy controls (Data Security & Privacy).", "The recommendation engine must be scalable to process user data and provide relevant recommendations for an increasing number of students and tutors (Scalability)."]'::jsonb, 1, 'DRAFT'::requirement_status_enum, FALSE, NULL, 'REQ-5', 5, FALSE, TRUE, 1, '2026-06-18 07:36:30.313159', '2026-06-18 07:36:30.313159') ON CONFLICT (id) DO NOTHING;
INSERT INTO requirements (id, project_id, title, description, type, priority, acceptance_criteria, owner_id, status, evidence_required, req_order, req_code, project_sub_id, is_deleted, ai_generated, created_by, created_at, updated_at) VALUES (107, 1, 'Online Payment Processing', 'The system supports online payment through multiple payment gateways. Students may purchase individual sessions or discounted tutoring packages.', 'FUNCTIONAL'::requirement_type_enum, 'CRITICAL'::priority_enum, '["When a student initiates a payment, all sensitive payment information must be encrypted and securely transmitted to the payment gateway, adhering to PCI DSS standards (Data Security & Privacy, Payment Processing Integrity).", "The payment processing system must be highly available to ensure uninterrupted transaction processing, especially during peak times (High Availability).", "Upon successful payment, the system must guarantee the integrity and accuracy of the transaction record and link it unequivocally to the corresponding booking or package purchase (Payment Processing Integrity).", "The payment infrastructure must be capable of processing a rapidly increasing volume of transactions without compromising integrity or performance (Scalability).", "In case of a payment failure, the system must notify the user, provide clear error messages, and ensure no partial charges are applied (Payment Processing Integrity)."]'::jsonb, 1, 'DRAFT'::requirement_status_enum, FALSE, NULL, 'REQ-6', 6, FALSE, TRUE, 1, '2026-06-18 07:36:30.315208', '2026-06-18 07:36:30.315208') ON CONFLICT (id) DO NOTHING;
INSERT INTO requirements (id, project_id, title, description, type, priority, acceptance_criteria, owner_id, status, evidence_required, req_order, req_code, project_sub_id, is_deleted, ai_generated, created_by, created_at, updated_at) VALUES (108, 1, 'Booking Confirmation Notifications', 'After successful payment, booking confirmation is sent via email and SMS to the student.', 'FUNCTIONAL'::requirement_type_enum, 'HIGH'::priority_enum, '["Upon successful payment and booking, confirmation notifications must be sent via email and SMS within 30 seconds (Real-time Scheduling Accuracy, High Availability).", "The content of the notifications must accurately reflect the booking details and payment status (Payment Processing Integrity).", "The notification system must be designed to scale to send a large volume of confirmations without delays (Scalability).", "All notification content containing personal data must be handled in compliance with data privacy policies (Data Security & Privacy)."]'::jsonb, 1, 'DRAFT'::requirement_status_enum, FALSE, NULL, 'REQ-7', 7, FALSE, TRUE, 1, '2026-06-18 07:36:30.316572', '2026-06-18 07:36:30.316572') ON CONFLICT (id) DO NOTHING;
INSERT INTO requirements (id, project_id, title, description, type, priority, acceptance_criteria, owner_id, status, evidence_required, req_order, req_code, project_sub_id, is_deleted, ai_generated, created_by, created_at, updated_at) VALUES (109, 1, 'Tutor Schedule and Booking Management', 'Tutors can manage their schedules, define available time slots, approve or reject booking requests, and request schedule changes or session cancellations.', 'FUNCTIONAL'::requirement_type_enum, 'HIGH'::priority_enum, '["When a tutor updates their availability, changes must be reflected across the system in real-time to maintain scheduling accuracy for students (Real-time Scheduling Accuracy).", "The tutor''s schedule management interface must be highly available, allowing tutors to manage their time without interruption (High Availability).", "All changes to schedules and booking requests must be securely logged and accessible only by authorized personnel (Data Security & Privacy).", "The system must scale to allow a large number of tutors to manage their schedules concurrently without performance degradation (Scalability)."]'::jsonb, 1, 'DRAFT'::requirement_status_enum, FALSE, NULL, 'REQ-8', 8, FALSE, TRUE, 1, '2026-06-18 07:36:30.316572', '2026-06-18 07:36:30.316572') ON CONFLICT (id) DO NOTHING;
INSERT INTO requirements (id, project_id, title, description, type, priority, acceptance_criteria, owner_id, status, evidence_required, req_order, req_code, project_sub_id, is_deleted, ai_generated, created_by, created_at, updated_at) VALUES (110, 1, 'Online Lesson Conduction and Material Management', 'Tutors can conduct online lessons, upload learning materials, assign homework, and evaluate students.', 'FUNCTIONAL'::requirement_type_enum, 'HIGH'::priority_enum, '["The online lesson platform must be highly available and stable to ensure uninterrupted learning sessions (High Availability).", "All uploaded learning materials and student evaluations must be securely stored and accessible only to the tutor and relevant student (Data Security & Privacy).", "The system must support the secure and accurate real-time communication and interaction necessary for online lessons (Real-time Scheduling Accuracy - for synchronous interaction).", "The storage and streaming of learning materials must be scalable to support a growing volume of content and concurrent users (Scalability)."]'::jsonb, 1, 'DRAFT'::requirement_status_enum, FALSE, NULL, 'REQ-9', 9, FALSE, TRUE, 1, '2026-06-18 07:36:30.318095', '2026-06-18 07:36:30.318095') ON CONFLICT (id) DO NOTHING;
INSERT INTO requirements (id, project_id, title, description, type, priority, acceptance_criteria, owner_id, status, evidence_required, req_order, req_code, project_sub_id, is_deleted, ai_generated, created_by, created_at, updated_at) VALUES (111, 1, 'Student Learning Progress Tracking', 'Students can attend classes, submit assignments, view lesson history, communicate with tutors through chat, rate completed sessions, and provide feedback. The platform stores learning progress, attendance records, completed assignments, and tutor evaluations.', 'FUNCTIONAL'::requirement_type_enum, 'HIGH'::priority_enum, '["Student learning progress, attendance, and assignment statuses must be updated and reflected in real-time, ensuring accuracy (Real-time Scheduling Accuracy).", "All student data, including chat communications, assignments, and feedback, must be securely stored and comply with strict data privacy regulations (Data Security & Privacy).", "The platform for tracking progress and communication must be highly available to allow continuous access and interaction (High Availability).", "The system for storing learning progress and related artifacts must be scalable to accommodate a large volume of data for many students over time (Scalability)."]'::jsonb, 1, 'DRAFT'::requirement_status_enum, FALSE, NULL, 'REQ-10', 10, FALSE, TRUE, 1, '2026-06-18 07:36:30.319119', '2026-06-18 07:36:30.319119') ON CONFLICT (id) DO NOTHING;
INSERT INTO requirements (id, project_id, title, description, type, priority, acceptance_criteria, owner_id, status, evidence_required, req_order, req_code, project_sub_id, is_deleted, ai_generated, created_by, created_at, updated_at) VALUES (112, 1, 'Managerial Platform Administration', 'Managers can manage tutors, students, schedules, payments, discount campaigns, reports, and system settings. Managers can approve tutor registrations and monitor overall platform performance.', 'FUNCTIONAL'::requirement_type_enum, 'CRITICAL'::priority_enum, '["Managerial actions related to schedules and payments must reflect accurately and immediately across the system (Real-time Scheduling Accuracy, Payment Processing Integrity).", "All administrative interfaces and functionalities must be highly available to ensure continuous platform oversight and management (High Availability).", "Access to managerial functions and sensitive data must be strictly controlled via role-based access, ensuring robust data security and privacy (Data Security & Privacy).", "The administrative backend must be scalable to efficiently manage a growing number of users, bookings, and payments without performance bottlenecks (Scalability).", "Monitoring tools must provide real-time insights into platform performance and financial transactions, ensuring data integrity (Payment Processing Integrity, Real-time Scheduling Accuracy)."]'::jsonb, 1, 'DRAFT'::requirement_status_enum, FALSE, NULL, 'REQ-11', 11, FALSE, TRUE, 1, '2026-06-18 07:36:30.321122', '2026-06-18 07:36:30.321122') ON CONFLICT (id) DO NOTHING;
INSERT INTO requirements (id, project_id, title, description, type, priority, acceptance_criteria, owner_id, status, evidence_required, req_order, req_code, project_sub_id, is_deleted, ai_generated, created_by, created_at, updated_at) VALUES (113, 1, 'Secure Authentication and Access Control', 'The system provides secure authentication and role-based access control (RBAC) to ensure users can only access features and data appropriate for their assigned roles.', 'SECURITY'::requirement_type_enum, 'CRITICAL'::priority_enum, '["The authentication mechanism must use industry-standard security protocols and robust encryption for all credentials and session tokens (Data Security & Privacy).", "Role-based access control must strictly enforce that users can only access data and functionalities explicitly authorized for their role, preventing unauthorized data exposure (Data Security & Privacy).", "The security infrastructure must be highly available, ensuring that authentication and authorization services do not become single points of failure (High Availability).", "The security system must be scalable to manage authentication and authorization for a rapidly growing user base without performance degradation (Scalability).", "Any access attempt to sensitive payment or scheduling data must be logged and monitored for suspicious activity (Payment Processing Integrity, Real-time Scheduling Accuracy, Data Security & Privacy)."]'::jsonb, 1, 'DRAFT'::requirement_status_enum, FALSE, NULL, 'REQ-12', 12, FALSE, TRUE, 1, '2026-06-18 07:36:30.322102', '2026-06-18 07:36:30.322102') ON CONFLICT (id) DO NOTHING;
INSERT INTO requirements (id, project_id, title, description, type, priority, acceptance_criteria, owner_id, status, evidence_required, req_order, req_code, project_sub_id, is_deleted, ai_generated, created_by, created_at, updated_at) VALUES (114, 1, 'Learning Analytics and Reporting Dashboards', 'The system provides learning analytics and reporting dashboards for insights into student progress, tutor performance, and overall platform operations.', 'FUNCTIONAL'::requirement_type_enum, 'HIGH'::priority_enum, '["Learning analytics must generate reports based on up-to-date data, providing accurate insights into learning progress and scheduling patterns (Real-time Scheduling Accuracy).", "Reporting dashboards must be highly available, allowing managers to access critical operational data without interruption (High Availability).", "All data used for analytics and reporting must be aggregated and presented in a way that protects individual student and tutor privacy (Data Security & Privacy).", "The analytics and reporting infrastructure must be scalable to process and store increasing volumes of historical data without impacting system performance (Scalability).", "Financial reports must accurately reflect payment transactions and discount campaigns, maintaining payment processing integrity (Payment Processing Integrity)."]'::jsonb, 1, 'DRAFT'::requirement_status_enum, FALSE, NULL, 'REQ-13', 13, FALSE, TRUE, 1, '2026-06-18 07:36:30.323104', '2026-06-18 07:36:30.323104') ON CONFLICT (id) DO NOTHING;
INSERT INTO requirements (id, project_id, title, description, type, priority, acceptance_criteria, owner_id, status, evidence_required, req_order, req_code, project_sub_id, is_deleted, ai_generated, created_by, created_at, updated_at) VALUES (115, 1, 'Automated Reminders and Notifications', 'The system provides automated reminders and notifications for upcoming sessions, assignment deadlines, or other important events.', 'FUNCTIONAL'::requirement_type_enum, 'HIGH'::priority_enum, '["Automated reminders for sessions must be sent at specified intervals to ensure real-time scheduling accuracy (Real-time Scheduling Accuracy).", "The notification system must be highly available, ensuring all critical reminders are delivered reliably (High Availability).", "The system must scale to send a large volume of automated reminders and notifications to a growing user base efficiently (Scalability).", "Personal information included in reminders and notifications must adhere to data privacy standards (Data Security & Privacy)."]'::jsonb, 1, 'DRAFT'::requirement_status_enum, FALSE, NULL, 'REQ-14', 14, FALSE, TRUE, 1, '2026-06-18 07:36:30.324643', '2026-06-18 07:36:30.324643') ON CONFLICT (id) DO NOTHING;
INSERT INTO use_cases (id, project_id, requirement_id, code, project_sub_id, name, status, version, precondition, postcondition, main_flow, alternative_flow, includes_list, extends_list, completeness_score, show_in_diagram, added_from_diagram, ai_generated, req_version_hash, is_deleted, created_by, created_at, updated_at) VALUES (108, 1, 102, 'P1-UC-1', 1, 'Securely Register Student Account', 'DRAFT', 'v1.0', 'System is operational and ready to accept new registrations.', 'A new student account is securely created and encrypted in the system, or the registration attempt failed due to security policies.', '{"steps": ["1. System receives a student''s registration request (via email or social account).", "2. System validates all input data for format, completeness, and potential security vulnerabilities.", "3. System generates a unique and secure identifier for the new student account.", "4. System encrypts sensitive student account information (e.g., password, personal details).", "5. System securely stores the encrypted account information in the database, protected from unauthorized access.", "6. System confirms the successful account creation to the student and logs the event."]}'::jsonb, '{"flows": [{"name": "Generated Alternative Flow", "steps": ["AF2: If input data is invalid or malicious:", "1. System rejects the registration request.", "2. System logs the attempted security breach.", "3. System displays an error message to the student.", "AF5: If secure storage fails or encounters an integrity issue:", "1. System logs the storage failure.", "2. System notifies the administrator.", "3. System attempts to roll back any partially created account data to maintain system integrity."]}]}'::jsonb, '[]'::jsonb, '[]'::jsonb, 100, TRUE, FALSE, TRUE, '44a0695948a279067634dd71b732012c', FALSE, 1, '2026-06-18 07:42:39.887372', '2026-06-18 07:42:39.887372') ON CONFLICT (id) DO NOTHING;
INSERT INTO use_cases (id, project_id, requirement_id, code, project_sub_id, name, status, version, precondition, postcondition, main_flow, alternative_flow, includes_list, extends_list, completeness_score, show_in_diagram, added_from_diagram, ai_generated, req_version_hash, is_deleted, created_by, created_at, updated_at) VALUES (109, 1, 102, 'P1-UC-2', 2, 'Securely Authenticate Student Login', 'DRAFT', 'v1.0', 'Student account exists and system is operational.', 'Student is securely authenticated and granted access to the system, or login failed due to security policies or invalid credentials.', '{"steps": ["1. System receives student login credentials (email/password or social token).", "2. System securely retrieves the corresponding encrypted account data.", "3. System validates the provided credentials against the stored data using secure hashing/comparison methods.", "4. System verifies the integrity of the login request (e.g., checks for replay attacks, brute-force attempts).", "5. System enforces strict data privacy protocols for the student''s personal information during session creation.", "6. System grants secure, authenticated access to the student''s personalized dashboard.", "7. System logs the successful login event for auditing and security monitoring."]}'::jsonb, '{"flows": [{"name": "Generated Alternative Flow", "steps": ["AF3: If credentials are invalid or incorrect:", "1. System denies access.", "2. System logs the failed login attempt.", "3. System may initiate a temporary account lockout policy after multiple failed attempts.", "AF4: If login request integrity check fails (e.g., suspected malicious activity):", "1. System denies access immediately.", "2. System logs the potential security threat and alerts security personnel.", "AF6: If secure access cannot be granted due to an internal system error:", "1. System logs the error.", "2. System denies access and notifies the student of a technical issue, advising them to try again later."]}]}'::jsonb, '[]'::jsonb, '[]'::jsonb, 100, TRUE, FALSE, TRUE, '44a0695948a279067634dd71b732012c', FALSE, 1, '2026-06-18 07:42:39.920418', '2026-06-18 07:42:39.920418') ON CONFLICT (id) DO NOTHING;
INSERT INTO use_cases (id, project_id, requirement_id, code, project_sub_id, name, status, version, precondition, postcondition, main_flow, alternative_flow, includes_list, extends_list, completeness_score, show_in_diagram, added_from_diagram, ai_generated, req_version_hash, is_deleted, created_by, created_at, updated_at) VALUES (110, 1, 103, 'P1-UC-3', 3, 'Search for Tutors', 'DRAFT', 'v1.0', 'Student is logged in. A database of tutor profiles is available in the system.', 'Student views a filtered list of tutors matching the specified criteria, or a message indicating no matches.', '{"steps": ["1. Student navigates to the tutor search interface within the system.", "2. Student enters desired search criteria into the search fields (e.g., subject, expertise, language, teaching style, hourly rate, rating).", "3. Student optionally applies filters for further refinement (e.g., availability).", "4. Student initiates the search.", "5. System processes the search query, applying the specified criteria and filters to the tutor profile database.", "6. System retrieves all matching tutor profiles, ensuring adherence to data privacy regulations.", "7. System displays a list of the matching tutors, showing summary information for each (e.g., name, rating, main subjects)."]}'::jsonb, '{"flows": [{"name": "Generated Alternative Flow", "steps": ["AF3: If student enters no criteria and performs search:", "1. System displays a list of all available tutor profiles (or a default recommended list).", "AF6: If no tutors match the specified search and filter criteria:", "1. System displays a message informing the student that no tutors were found matching their selection.", "2. System may suggest broadening the search criteria."]}]}'::jsonb, '["115"]'::jsonb, '[]'::jsonb, 100, TRUE, FALSE, TRUE, '761a3e85a4541995f1d99209a67641a5', FALSE, 1, '2026-06-18 07:42:39.921401', '2026-06-18 08:17:11.203985') ON CONFLICT (id) DO NOTHING;
INSERT INTO use_cases (id, project_id, requirement_id, code, project_sub_id, name, status, version, precondition, postcondition, main_flow, alternative_flow, includes_list, extends_list, completeness_score, show_in_diagram, added_from_diagram, ai_generated, req_version_hash, is_deleted, created_by, created_at, updated_at) VALUES (111, 1, 104, 'P1-UC-4', 4, 'View Tutor Profile', 'DRAFT', 'v1.0', 'Student is logged in. A specific tutor profile exists and is accessible.', 'Student views the comprehensive details of the selected tutor, with all displayed information being accurate and respecting data privacy.', '{"steps": ["1. Student selects a tutor''s summary from a search result, recommendation list, or direct link.", "2. System retrieves the comprehensive tutor profile information from the database.", "3. System verifies student authorization to view specific profile details, ensuring sensitive information is only shown to authorized viewers.", "4. System ensures all displayed information (e.g., educational background, certifications, experience, subjects taught, reviews, teaching methods) is accurate and up-to-date.", "5. System displays the complete tutor profile on the screen, adhering to data privacy and availability requirements."]}'::jsonb, '{"flows": [{"name": "Generated Alternative Flow", "steps": ["AF1: If the student attempts to view a non-existent or deactivated tutor profile:", "1. System displays an error message: ''Tutor profile not found or unavailable''.", "AF3: If certain sensitive details in the profile are restricted and the student is not authorized to view them:", "1. System displays the tutor profile with the restricted information hidden, masked, or redacted.", "AF4: If there is a temporary issue retrieving all profile data or ensuring its real-time accuracy:", "1. System displays a warning indicating that some data might be incomplete or stale.", "2. System attempts to refresh the data or provides a fallback message."]}]}'::jsonb, '[]'::jsonb, '[]'::jsonb, 100, TRUE, FALSE, TRUE, '6b062cd24c046d7e40028f3409fc0e68', FALSE, 1, '2026-06-18 07:42:39.924931', '2026-06-18 07:42:39.924931') ON CONFLICT (id) DO NOTHING;
INSERT INTO use_cases (id, project_id, requirement_id, code, project_sub_id, name, status, version, precondition, postcondition, main_flow, alternative_flow, includes_list, extends_list, completeness_score, show_in_diagram, added_from_diagram, ai_generated, req_version_hash, is_deleted, created_by, created_at, updated_at) VALUES (112, 1, 105, 'P1-UC-5', 5, 'Book Tutoring Session', 'DRAFT', 'v1.0', 'Student is logged in. Tutor has defined available time slots. Student has selected a tutor.', 'A tutoring session is successfully booked and paid for, with confirmation notifications sent to the student, or the booking process was cancelled/failed.', '{"steps": ["1. Student selects a desired tutor to book a session with.", "2. System displays the tutor''s available time slots, dates, and learning modes (online/offline).", "3. Student selects a preferred date, time slot, session duration, and learning mode.", "4. System verifies that the chosen time slot is still available and prevents any double-bookings in real-time.", "5. System calculates the total cost for the selected session based on the tutor''s rate and duration.", "6. System presents a summary of the session details and the total cost to the student for confirmation.", "7. Student reviews the details and confirms the booking.", "8. System initiates the payment process, including ''Process Online Payment''.", "9. Upon successful payment, System updates the booking status to ''Confirmed'' and triggers ''Send Booking Confirmation Notifications''.", "10. System displays a booking confirmation message to the student."]}'::jsonb, '{"flows": [{"name": "Generated Alternative Flow", "steps": ["AF2: If the selected tutor has no available time slots:", "1. System displays a message: ''This tutor has no available slots at the moment.''", "2. System may prompt the student to contact the tutor, check back later, or select another tutor.", "AF4: If the chosen time slot becomes unavailable before the student confirms:", "1. System notifies the student that the slot is no longer available.", "2. System prompts the student to select another available slot.", "AF7: If the student cancels the booking confirmation:", "1. System cancels the booking process.", "2. System returns the student to the previous step or tutor profile page."]}]}'::jsonb, '[]'::jsonb, '[]'::jsonb, 100, TRUE, FALSE, TRUE, 'be838a7cb84e28e3bcd9597fa76eb36b', FALSE, 1, '2026-06-18 07:42:39.928036', '2026-06-18 08:19:19.202391') ON CONFLICT (id) DO NOTHING;
INSERT INTO use_cases (id, project_id, requirement_id, code, project_sub_id, name, status, version, precondition, postcondition, main_flow, alternative_flow, includes_list, extends_list, completeness_score, show_in_diagram, added_from_diagram, ai_generated, req_version_hash, is_deleted, created_by, created_at, updated_at) VALUES (113, 1, 105, 'P1-UC-6', 6, 'Define Tutor Availability', 'DRAFT', 'v1.0', 'Tutor is logged in and has access to their schedule management interface.', 'Tutor''s schedule is updated with new or modified available time slots, visible for student bookings.', '{"steps": ["1. Tutor navigates to their schedule management interface within the system.", "2. System displays the tutor''s current available time slots and existing bookings.", "3. Tutor selects dates and defines new available time slots, specifying duration and learning modes (online/offline).", "4. Tutor submits the changes to their availability.", "5. System validates the new availability data against existing bookings and system rules (e.g., minimum notice period).", "6. System updates the tutor''s availability across the system, ensuring real-time reflection for students.", "7. System confirms the successful schedule update to the tutor."]}'::jsonb, '{"flows": [{"name": "Generated Alternative Flow", "steps": ["AF5: If the defined availability conflicts with existing bookings or system rules:", "1. System flags the conflicts (e.g., overlapping slots, insufficient break time).", "2. System prompts the tutor to review and resolve the identified conflicts.", "AF6: If the system fails to update the availability due to a technical issue:", "1. System logs the error and notifies the administrator.", "2. System notifies the tutor of the failure to update and advises them to retry."]}]}'::jsonb, '[]'::jsonb, '[]'::jsonb, 100, TRUE, FALSE, TRUE, 'be838a7cb84e28e3bcd9597fa76eb36b', FALSE, 1, '2026-06-18 07:42:39.930041', '2026-06-18 07:42:39.930041') ON CONFLICT (id) DO NOTHING;
INSERT INTO use_cases (id, project_id, requirement_id, code, project_sub_id, name, status, version, precondition, postcondition, main_flow, alternative_flow, includes_list, extends_list, completeness_score, show_in_diagram, added_from_diagram, ai_generated, req_version_hash, is_deleted, created_by, created_at, updated_at) VALUES (114, 1, 106, 'P1-UC-7', 7, 'Receive Tutor Recommendations', 'DRAFT', 'v1.0', 'Student is logged in. System has access to tutor profiles and potentially student learning history.', 'Student views a list of recommended tutors based on subject requirements and learning history.', '{"steps": ["1. Student indicates a need for a tutor without selecting a specific one (e.g., by selecting a subject, or by navigating to a ''recommendations'' section).", "2. System retrieves the student''s current subject requirements and past learning history, ensuring adherence to data privacy controls.", "3. System processes this data using its recommendation engine (optionally AI-powered) to identify suitable tutors.", "4. System retrieves the profiles of the identified suitable tutors.", "5. System displays a list of recommended tutors to the student, including relevant details like rating, subjects, and hourly rate.", "6. Student can then choose to view a recommended tutor''s full profile or initiate a booking."]}'::jsonb, '{"flows": [{"name": "Generated Alternative Flow", "steps": ["AF2: If no learning history is available for the student:", "1. System provides recommendations based solely on specified subject requirements, popular tutors, or general criteria.", "AF4: If no suitable tutors can be found based on the available data:", "1. System displays a message: ''No recommendations available at this time.''", "2. System may prompt the student to broaden their subject requirements or explore other search options."]}]}'::jsonb, '[]'::jsonb, '[]'::jsonb, 100, TRUE, FALSE, TRUE, 'a0f17114e39723671060218acf5be6b1', FALSE, 1, '2026-06-18 07:42:39.932042', '2026-06-18 07:42:39.932042') ON CONFLICT (id) DO NOTHING;
INSERT INTO use_cases (id, project_id, requirement_id, code, project_sub_id, name, status, version, precondition, postcondition, main_flow, alternative_flow, includes_list, extends_list, completeness_score, show_in_diagram, added_from_diagram, ai_generated, req_version_hash, is_deleted, created_by, created_at, updated_at) VALUES (115, 1, 107, 'P1-UC-8', 8, 'Process Online Payment', 'DRAFT', 'v1.0', 'A transaction (e.g., session booking, package purchase) has been initiated and requires payment.', 'Payment is successfully processed, the transaction record is securely stored and linked, and the originating transaction status is updated, or payment failed.', '{"steps": ["1. System receives a payment initiation request from an originating use case with transaction details.", "2. System securely redirects the student to a chosen payment gateway or presents available payment options.", "3. Student enters payment information (e.g., credit card details) into the payment gateway interface.", "4. Payment Gateway securely processes the payment transaction.", "5. Payment Gateway sends the transaction result (success/failure) back to the system.", "6. System encrypts and securely stores the payment record, linking it unequivocally to the corresponding booking or package purchase.", "7. System updates the status of the originating transaction (e.g., booking, package purchase) to ''Paid'' or ''Pending''.", "8. System confirms payment success to the student and notifies the originating use case."]}'::jsonb, '{"flows": [{"name": "Generated Alternative Flow", "steps": ["AF2: If student cancels the payment process before entering details:", "1. System receives cancellation notification from the student or payment gateway.", "2. System cancels the payment initiation and notifies the originating use case of the cancellation.", "AF5: If the Payment Gateway fails or declines the payment:", "1. System receives a payment failure notification from the payment gateway.", "2. System notifies the student of the payment failure with clear error messages.", "3. System ensures no partial charges are applied and the transaction integrity is maintained.", "4. System logs the payment failure and details of the originating transaction.", "5. System notifies the originating use case of the payment failure.", "AF6: If secure storage of the payment record fails after successful payment by gateway:", "1. System logs the storage error.", "2. System notifies the administrator for manual reconciliation.", "3. System temporarily holds the originating transaction as ''pending verification'' to prevent data inconsistency."]}]}'::jsonb, '[]'::jsonb, '[]'::jsonb, 100, TRUE, FALSE, TRUE, 'cdc42163d3b9ef10683d9bd8b8a1479e', FALSE, 1, '2026-06-18 07:42:39.933040', '2026-06-18 07:42:39.933040') ON CONFLICT (id) DO NOTHING;
INSERT INTO use_cases (id, project_id, requirement_id, code, project_sub_id, name, status, version, precondition, postcondition, main_flow, alternative_flow, includes_list, extends_list, completeness_score, show_in_diagram, added_from_diagram, ai_generated, req_version_hash, is_deleted, created_by, created_at, updated_at) VALUES (116, 1, 108, 'P1-UC-9', 9, 'Send Booking Confirmation Notifications', 'DRAFT', 'v1.0', 'A tutoring session has been successfully booked and paid for.', 'Booking confirmation notifications are sent via email and SMS to the student.', '{"steps": ["1. System receives a trigger indicating a successful booking and payment.", "2. System retrieves the student''s registered email address and phone number.", "3. System composes an email notification containing all accurate booking details (date, time, tutor, mode, duration) and payment status.", "4. System composes an SMS notification with essential booking details.", "5. System sends the email notification to the student''s email address.", "6. System sends the SMS notification to the student''s phone number.", "7. System logs the successful sending of both notifications for auditing purposes."]}'::jsonb, '{"flows": [{"name": "Generated Alternative Flow", "steps": ["AF2: If student''s contact information (email or phone) is missing or invalid:", "1. System logs the error for missing/invalid contact details.", "2. System flags the issue for administrator review to attempt manual contact or data correction.", "AF5: If email sending fails:", "1. System logs the email sending failure.", "2. System may attempt a retry or flag for administrator intervention.", "AF6: If SMS sending fails:", "1. System logs the SMS sending failure.", "2. System may attempt a retry or flag for administrator intervention."]}]}'::jsonb, '[]'::jsonb, '[]'::jsonb, 100, TRUE, FALSE, TRUE, 'eaf2e6eab533820be6d22f42cf3667ee', FALSE, 1, '2026-06-18 07:42:39.935040', '2026-06-18 07:42:39.935040') ON CONFLICT (id) DO NOTHING;
INSERT INTO use_cases (id, project_id, requirement_id, code, project_sub_id, name, status, version, precondition, postcondition, main_flow, alternative_flow, includes_list, extends_list, completeness_score, show_in_diagram, added_from_diagram, ai_generated, req_version_hash, is_deleted, created_by, created_at, updated_at) VALUES (117, 1, 109, 'P1-UC-10', 10, 'Manage Tutor Schedule and Bookings', 'DRAFT', 'v1.0', 'Tutor is logged in and has access to their schedule and booking management interface.', 'Tutor''s schedule, booking requests, or session statuses are updated according to the tutor''s actions.', '{"steps": ["1. Tutor navigates to their schedule and booking management interface.", "2. System displays the tutor''s current schedule, available time slots, and a list of pending, confirmed, or completed booking requests.", "3. Tutor selects one of the following actions:", "a. Define/Update Availability: Tutor performs actions to modify their available time slots (includes ''Define Tutor Availability'' UC).", "b. Approve Booking Request: Tutor selects a pending booking request and confirms it.", "c. Reject Booking Request: Tutor selects a pending booking request and declines it, providing a reason.", "d. Request Schedule Change: Tutor requests a change to a confirmed session''s date/time.", "e. Request Session Cancellation: Tutor requests to cancel a confirmed session.", "4. System processes the selected action, updating the tutor''s schedule, booking status, or initiating relevant workflows.", "5. (For b & c) System notifies the student of the booking approval or rejection.", "6. (For d & e) System may initiate a workflow for student/admin approval if required for changes/cancellations.", "7. System updates records in real-time and confirms the action to the tutor."]}'::jsonb, '{"flows": [{"name": "Generated Alternative Flow", "steps": ["AF3a: If defining/updating availability leads to conflicts (as per ''Define Tutor Availability'' AF):", "1. System guides the tutor through resolving the conflicts.", "AF3b: If a booking request has expired or become invalid before approval:", "1. System informs the tutor that the request cannot be approved.", "2. System provides options to contact the student or remove the invalid request.", "AF4: If the system fails to process an update or action due to a technical issue:", "1. System displays an error message to the tutor.", "2. System logs the failure and notifies relevant support personnel."]}]}'::jsonb, '[]'::jsonb, '[]'::jsonb, 100, TRUE, FALSE, TRUE, 'c088f8d28cf64c65966e89d41e4b0356', FALSE, 1, '2026-06-18 07:42:39.936040', '2026-06-18 07:56:28.358970') ON CONFLICT (id) DO NOTHING;
INSERT INTO use_cases (id, project_id, requirement_id, code, project_sub_id, name, status, version, precondition, postcondition, main_flow, alternative_flow, includes_list, extends_list, completeness_score, show_in_diagram, added_from_diagram, ai_generated, req_version_hash, is_deleted, created_by, created_at, updated_at) VALUES (118, 1, 110, 'P1-UC-11', 11, 'Conduct Online Lesson and Manage Materials', 'DRAFT', 'v1.0', 'Tutor is logged in. An online lesson is scheduled and active or upcoming for the tutor.', 'Online lesson conducted, learning materials uploaded, homework assigned, or student evaluated, with all data securely stored.', '{"steps": ["1. Tutor initiates or joins an online lesson from their personal dashboard at the scheduled time.", "2. System provides access to the online lesson platform, including tools for video conferencing, screen sharing, and chat.", "3. During or after the lesson, Tutor performs one or more of the following actions:", "a. Uploads learning materials relevant to the lesson (e.g., documents, presentations, links).", "b. Assigns homework to the student, specifying due dates and instructions.", "c. Evaluates student performance and progress for the session.", "4. System securely stores all uploaded materials, homework assignments, and student evaluation records, ensuring they are accessible to the relevant student and tutor only.", "5. System updates the lesson status and confirms the successful completion of the action to the tutor."]}'::jsonb, '{"flows": [{"name": "Generated Alternative Flow", "steps": ["AF1: If the online lesson platform cannot be initiated or maintained due to technical issues:", "1. System displays an error message to the tutor and student.", "2. System logs the error and notifies technical support for investigation and resolution.", "AF3a: If an attempt to upload learning materials fails:", "1. System notifies the tutor of the upload failure.", "2. System provides options to retry the upload or save as draft.", "AF4: If the secure storage of materials, assignments, or evaluations fails:", "1. System logs the storage error.", "2. System notifies the administrator and the tutor to ensure data integrity and prevent loss."]}]}'::jsonb, '[]'::jsonb, '[]'::jsonb, 100, TRUE, FALSE, TRUE, '545abd896768620a5547b5c6d7d47cdd', FALSE, 1, '2026-06-18 07:42:39.936545', '2026-06-18 07:42:39.936545') ON CONFLICT (id) DO NOTHING;
INSERT INTO use_cases (id, project_id, requirement_id, code, project_sub_id, name, status, version, precondition, postcondition, main_flow, alternative_flow, includes_list, extends_list, completeness_score, show_in_diagram, added_from_diagram, ai_generated, req_version_hash, is_deleted, created_by, created_at, updated_at) VALUES (119, 1, 111, 'P1-UC-12', 12, 'Manage Learning Progress and Interact', 'DRAFT', 'v1.0', 'Student is logged in. Student has active or completed tutoring sessions or assignments.', 'Student''s learning progress is updated, communication with tutors is facilitated, or session feedback is recorded.', '{"steps": ["1. Student navigates to their learning progress dashboard within the system.", "2. System displays the student''s lesson history, ongoing assignments, tutor evaluations, and options for interaction.", "3. Student performs one or more of the following actions:", "a. Submits a completed assignment.", "b. Views details of past lesson history, including materials and notes.", "c. Initiates or responds to a chat conversation with their tutor.", "d. Rates a recently completed tutoring session.", "e. Provides written feedback on a session or tutor.", "4. (If submits assignment) System securely records the assignment submission, updating its status.", "5. (If chat) System facilitates real-time communication between student and tutor, storing the chat history.", "6. (If rates/feedback) System records the rating and feedback, linking it to the specific session or tutor.", "7. System updates the student''s learning progress records and confirms the action to the student."]}'::jsonb, '{"flows": [{"name": "Generated Alternative Flow", "steps": ["AF3a: If assignment submission fails (e.g., file too large, network error):", "1. System notifies the student of the failure.", "2. System provides options to retry the submission.", "AF3c: If a chat session cannot be initiated or maintained due to technical issues:", "1. System displays an error message.", "2. System logs the error and suggests alternative communication methods if available.", "AF6: If secure storage of chat messages, ratings, or feedback fails:", "1. System logs the storage error.", "2. System notifies the administrator to address the data integrity issue."]}]}'::jsonb, '[]'::jsonb, '[]'::jsonb, 100, TRUE, FALSE, TRUE, '0a2bde20a5ace0ad708731964e1df2f6', FALSE, 1, '2026-06-18 07:42:39.941547', '2026-06-18 07:42:39.941547') ON CONFLICT (id) DO NOTHING;
INSERT INTO use_cases (id, project_id, requirement_id, code, project_sub_id, name, status, version, precondition, postcondition, main_flow, alternative_flow, includes_list, extends_list, completeness_score, show_in_diagram, added_from_diagram, ai_generated, req_version_hash, is_deleted, created_by, created_at, updated_at) VALUES (120, 1, 112, 'P1-UC-13', 13, 'Perform Platform Administration', 'DRAFT', 'v1.0', 'Manager is logged in and has the necessary administrative privileges.', 'Platform entities (tutors, students, schedules, payments, campaigns, settings) are managed, or reports and performance data are viewed.', '{"steps": ["1. Manager logs in to the administrative platform using their credentials.", "2. System presents the managerial dashboard, displaying an overview of platform status and available administration modules.", "3. Manager selects a specific administrative function:", "a. Manage Tutors (e.g., approve tutor registrations, edit tutor profiles, activate/deactivate accounts).", "b. Manage Students (e.g., view student profiles, suspend accounts, reset passwords).", "c. Manage Schedules (e.g., override tutor availability, resolve booking conflicts).", "d. Manage Payments (e.g., view transaction history, initiate refunds, reconcile discrepancies).", "e. Manage Discount Campaigns (e.g., create new campaigns, modify existing ones, track performance).", "f. View Reports (e.g., generate financial reports, usage statistics, performance analytics).", "g. Manage System Settings (e.g., configure platform parameters, update security policies).", "4. System retrieves/processes the requested data or executes the chosen action, ensuring data integrity, security, and real-time accuracy.", "5. System displays the results of the query or confirms the successful execution of the action to the manager.", "6. System logs all managerial actions and data access for audit and compliance purposes."]}'::jsonb, '{"flows": [{"name": "Generated Alternative Flow", "steps": ["AF3: If the manager attempts to access a function or perform an action without sufficient privileges:", "1. System denies access to the function.", "2. System logs the unauthorized attempt and notifies security personnel.", "AF4: If a data retrieval or action execution fails due to a technical issue:", "1. System displays an appropriate error message to the manager.", "2. System logs the failure details and notifies relevant technical support personnel.", "AF4: When viewing sensitive data (e.g., payment details, personal student information):", "1. System ensures that sensitive data is masked, encrypted, or displayed only with explicit authorization and secure protocols, adhering to privacy regulations."]}]}'::jsonb, '[]'::jsonb, '[]'::jsonb, 100, TRUE, FALSE, TRUE, '3066b492431c1cef7553985551f9e70d', FALSE, 1, '2026-06-18 07:42:39.943051', '2026-06-18 07:42:39.943051') ON CONFLICT (id) DO NOTHING;
INSERT INTO use_cases (id, project_id, requirement_id, code, project_sub_id, name, status, version, precondition, postcondition, main_flow, alternative_flow, includes_list, extends_list, completeness_score, show_in_diagram, added_from_diagram, ai_generated, req_version_hash, is_deleted, created_by, created_at, updated_at) VALUES (121, 1, 113, 'P1-UC-14', 14, 'Configure Role-Based Access Control', 'DRAFT', 'v1.0', 'Manager is authenticated and authorized to manage security settings.', 'System access control rules are updated according to the manager''s configuration.', '{"steps": ["1. Manager accesses the security administration module.", "2. System displays current roles and their associated permissions.", "3. Manager selects a role or creates a new one.", "4. Manager assigns or revokes permissions for the selected role for various system features and data.", "5. Manager confirms the changes.", "6. System updates the role-based access control policies.", "7. System confirms successful update."]}'::jsonb, '{"flows": [{"name": "Generated Alternative Flow", "steps": ["AF4: If Manager attempts to assign invalid permissions:", "1. System displays an error message indicating invalid permission assignment.", "2. Manager corrects the permissions.", "AF6: If System fails to update policies:", "1. System logs the error and notifies the Manager."]}]}'::jsonb, '[]'::jsonb, '[]'::jsonb, 100, TRUE, FALSE, TRUE, '5b4d2f025072d697750b8004af8adea1', FALSE, 1, '2026-06-18 07:44:24.808943', '2026-06-18 07:45:56.365029') ON CONFLICT (id) DO NOTHING;
INSERT INTO use_cases (id, project_id, requirement_id, code, project_sub_id, name, status, version, precondition, postcondition, main_flow, alternative_flow, includes_list, extends_list, completeness_score, show_in_diagram, added_from_diagram, ai_generated, req_version_hash, is_deleted, created_by, created_at, updated_at) VALUES (122, 1, 113, 'P1-UC-15', 15, 'Monitor Security Logs', 'DRAFT', 'v1.0', 'Manager is authenticated and authorized to view security logs.', 'Manager has reviewed security events; system continues to log access attempts.', '{"steps": ["1. Manager accesses the security monitoring dashboard.", "2. System displays a list of recent access attempts, security events, and audit trails, including attempts to sensitive payment or scheduling data.", "3. Manager filters or searches the logs based on criteria (e.g., user, date, event type).", "4. System displays filtered log entries.", "5. Manager reviews suspicious activities or audit reports.", "6. Manager exits the monitoring dashboard."]}'::jsonb, '{"flows": [{"name": "Generated Alternative Flow", "steps": ["AF3: If no logs match the filter criteria:", "1. System displays a message \"No matching log entries found.\""]}]}'::jsonb, '[]'::jsonb, '[]'::jsonb, 100, TRUE, FALSE, TRUE, '5b4d2f025072d697750b8004af8adea1', FALSE, 1, '2026-06-18 07:44:24.824504', '2026-06-18 07:44:24.824504') ON CONFLICT (id) DO NOTHING;
INSERT INTO use_cases (id, project_id, requirement_id, code, project_sub_id, name, status, version, precondition, postcondition, main_flow, alternative_flow, includes_list, extends_list, completeness_score, show_in_diagram, added_from_diagram, ai_generated, req_version_hash, is_deleted, created_by, created_at, updated_at) VALUES (123, 1, 114, 'P1-UC-16', 16, 'View Learning Analytics Dashboard', 'DRAFT', 'v1.0', 'Manager is authenticated and authorized to access learning analytics. System has collected sufficient data.', 'Manager has reviewed learning analytics and reporting data; system continues to collect and process data.', '{"steps": ["1. Manager accesses the learning analytics and reporting module.", "2. System displays the main dashboard with an overview of platform operations, tutor performance metrics, and aggregated student progress insights.", "3. Manager selects specific reports or filters data (e.g., by date range, tutor, student cohort).", "4. System generates and displays detailed reports or updated dashboard views, including financial reports.", "5. Manager analyzes the displayed data for insights.", "6. Manager exits the dashboard."]}'::jsonb, '{"flows": [{"name": "Generated Alternative Flow", "steps": ["AF4: If no data is available for the selected criteria:", "1. System displays a \"No data available\" message.", "AF4: If report generation fails:", "1. System logs the error and displays an error message to the Manager."]}]}'::jsonb, '[]'::jsonb, '[]'::jsonb, 100, TRUE, FALSE, TRUE, '7002efa6e21c518c384a7e86d27cc50c', FALSE, 1, '2026-06-18 07:44:24.826536', '2026-06-18 07:45:56.365029') ON CONFLICT (id) DO NOTHING;
INSERT INTO use_cases (id, project_id, requirement_id, code, project_sub_id, name, status, version, precondition, postcondition, main_flow, alternative_flow, includes_list, extends_list, completeness_score, show_in_diagram, added_from_diagram, ai_generated, req_version_hash, is_deleted, created_by, created_at, updated_at) VALUES (124, 1, 115, 'P1-UC-17', 17, 'Send Automated Reminders and Notifications', 'DRAFT', 'v1.0', 'An event requiring a reminder (e.g., upcoming session, assignment deadline) is scheduled in the system.', 'Relevant actors (Student, Tutor) have received automated reminders/notifications.', '{"steps": ["1. System identifies an event requiring a reminder/notification based on predefined rules and schedules.", "2. System retrieves the recipient(s) (Student, Tutor) and relevant event details.", "3. System composes the reminder/notification message, ensuring data privacy standards are met.", "4. System sends the reminder/notification via the user''s preferred communication channel (e.g., email, in-app notification).", "5. System logs the successful delivery of the reminder/notification."]}'::jsonb, '{"flows": [{"name": "Generated Alternative Flow", "steps": ["AF4: If a recipient''s preferred communication channel is unavailable:", "1. System attempts to send via an alternative channel.", "2. If all channels fail, System logs the delivery failure."]}]}'::jsonb, '[]'::jsonb, '[]'::jsonb, 83, TRUE, FALSE, TRUE, 'e11ab7f985b74521e9b8fa2a049c4f5d', FALSE, 1, '2026-06-18 07:44:24.830054', '2026-06-18 07:44:24.830054') ON CONFLICT (id) DO NOTHING;
INSERT INTO use_cases (id, project_id, requirement_id, code, project_sub_id, name, status, version, precondition, postcondition, main_flow, alternative_flow, includes_list, extends_list, completeness_score, show_in_diagram, added_from_diagram, ai_generated, req_version_hash, is_deleted, created_by, created_at, updated_at) VALUES (125, 1, 115, 'P1-UC-18', 18, 'Manage Reminder and Notification Preferences', 'DRAFT', 'v1.0', 'Actor is authenticated.', 'Actor''s preferences for receiving reminders and notifications are updated.', '{"steps": ["1. Actor navigates to their profile settings or notification preferences section.", "2. System displays current reminder and notification settings (e.g., preferred channels, timing for session reminders, types of events to be notified about).", "3. Actor modifies their preferences.", "4. Actor saves the changes.", "5. System updates the actor''s notification preferences.", "6. System confirms successful update."]}'::jsonb, '{"flows": [{"name": "Generated Alternative Flow", "steps": ["AF3: If Actor attempts to set invalid preferences:", "1. System displays an error message.", "2. Actor corrects the preferences."]}]}'::jsonb, '[]'::jsonb, '[]'::jsonb, 100, TRUE, FALSE, TRUE, 'e11ab7f985b74521e9b8fa2a049c4f5d', FALSE, 1, '2026-06-18 07:44:24.832044', '2026-06-18 07:45:56.366202') ON CONFLICT (id) DO NOTHING;
